local function RUN()
	local stage = B64(table.concat(CH))
	stage = XOR(stage, K2)
	stage = XOR(stage, K1)
	local L = loadstring or load
	if type(L) ~= "function" then
		error("[STELEX] executor missing loadstring", 0)
	end
	local fn, err = L(stage)
	if not fn then
		error("[STELEX] load fail: " .. tostring(err), 0)
	end
	pcall(function()
		if getgenv then
			getgenv()._StelexProtected = true
			getgenv()._StelexAuthor = "Veno"
		end
	end)
	fn()
end

local ok, err = pcall(RUN)
if not ok then
	warn("[STELEX] " .. tostring(err))
end
